begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id,email_confirmed_at) values (md5('smart_a')::uuid,clock_timestamp()),(md5('smart_b')::uuid,clock_timestamp());
insert into public.profiles(id,display_name) values(md5('smart_a')::uuid,'Smart A'),(md5('smart_b')::uuid,'Smart B');
insert into public.account_preferences(owner_id) values(md5('smart_a')::uuid);
select is((select display_weight_unit from public.account_preferences where owner_id=md5('smart_a')::uuid),'lb','new account default is pounds');
select ok(not has_column_privilege('authenticated','public.workout_sets','inputs_confirmed','UPDATE'),'confirmed provenance cannot be rewritten by clients');
select ok(not has_function_privilege('anon','public.initialize_workout_sets(uuid,integer)','execute'),'anonymous initialization denied');
select ok(not has_function_privilege('service_role','public.previous_exercise_sets(uuid)','execute'),'service role history RPC not granted');
insert into public.workout_sessions(id,owner_id,name,status,completion_status,started_at,finished_at) values(md5('smart_meaningful')::uuid,md5('smart_a')::uuid,'History','completed','partial','2019-12-31','2020-01-01');
insert into public.workout_exercises(id,owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot,removed_at) select md5('smart_item_meaningful')::uuid,md5('smart_a')::uuid,md5('smart_meaningful')::uuid,1,id,name,null from public.exercises where slug='barbell_bench_press';
insert into public.workout_sets(id,owner_id,workout_exercise_id,position,set_type,status,actual_reps,actual_weight_kg,completed_at,deleted_at,entered_weight,entered_unit) values(md5('smart_meaningful_1')::uuid,md5('smart_a')::uuid,md5('smart_item_meaningful')::uuid,1,'warm_up','completed',8,22.68,'2020-01-01',null,50,'lb');
insert into public.workout_sets(id,owner_id,workout_exercise_id,position,set_type,status,actual_reps,actual_weight_kg,completed_at,deleted_at,entered_weight,entered_unit) values(md5('smart_meaningful_2')::uuid,md5('smart_a')::uuid,md5('smart_item_meaningful')::uuid,2,'working','completed',8,22.68,'2020-01-01',null,50,'lb');
insert into public.workout_sets(id,owner_id,workout_exercise_id,position,set_type,status,actual_reps,actual_weight_kg,completed_at,deleted_at,entered_weight,entered_unit) values(md5('smart_meaningful_3')::uuid,md5('smart_a')::uuid,md5('smart_item_meaningful')::uuid,3,'drop','completed',8,22.68,'2020-01-01',null,50,'lb');
insert into public.workout_sets(id,owner_id,workout_exercise_id,position,set_type,status,actual_reps,actual_weight_kg,completed_at,deleted_at,entered_weight,entered_unit) values(md5('smart_meaningful_4')::uuid,md5('smart_a')::uuid,md5('smart_item_meaningful')::uuid,4,'rest_pause','completed',8,22.68,'2020-01-01',null,50,'lb');
insert into public.workout_sets(id,owner_id,workout_exercise_id,position,set_type,status,actual_reps,actual_weight_kg,completed_at,deleted_at,entered_weight,entered_unit) values(md5('smart_meaningful_5')::uuid,md5('smart_a')::uuid,md5('smart_item_meaningful')::uuid,5,'working','completed',8,22.68,'2020-01-01','2020-01-01',50,'lb');
insert into public.workout_sets(id,owner_id,workout_exercise_id,position,set_type,status,actual_reps,actual_weight_kg,completed_at,deleted_at,entered_weight,entered_unit) values(md5('smart_meaningful_6')::uuid,md5('smart_a')::uuid,md5('smart_item_meaningful')::uuid,6,'working','pending',8,22.68,null,null,50,'lb');
insert into public.workout_sessions(id,owner_id,name,status,completion_status,started_at,finished_at) values(md5('smart_empty')::uuid,md5('smart_a')::uuid,'History','completed','partial','2019-12-31','2020-01-04');
insert into public.workout_exercises(id,owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot,removed_at) select md5('smart_item_empty')::uuid,md5('smart_a')::uuid,md5('smart_empty')::uuid,1,id,name,null from public.exercises where slug='barbell_bench_press';
insert into public.workout_sessions(id,owner_id,name,status,completion_status,started_at,finished_at) values(md5('smart_abandoned')::uuid,md5('smart_a')::uuid,'History','abandoned','partial','2019-12-31','2020-01-05');
insert into public.workout_exercises(id,owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot,removed_at) select md5('smart_item_abandoned')::uuid,md5('smart_a')::uuid,md5('smart_abandoned')::uuid,1,id,name,null from public.exercises where slug='barbell_bench_press';
insert into public.workout_sets(id,owner_id,workout_exercise_id,position,set_type,status,actual_reps,actual_weight_kg,completed_at,deleted_at,entered_weight,entered_unit) values(md5('smart_abandoned_1')::uuid,md5('smart_a')::uuid,md5('smart_item_abandoned')::uuid,1,'warm_up','completed',8,99,'2020-01-05',null,null,null);
insert into public.workout_sessions(id,owner_id,name,status,completion_status,started_at,finished_at) values(md5('smart_removed')::uuid,md5('smart_a')::uuid,'History','completed','partial','2019-12-31','2020-01-06');
insert into public.workout_exercises(id,owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot,removed_at) select md5('smart_item_removed')::uuid,md5('smart_a')::uuid,md5('smart_removed')::uuid,1,id,name,'2020-01-08' from public.exercises where slug='barbell_bench_press';
-- Privileged rollback-only import fixture for an otherwise unreachable removed-history edge.
alter table public.workout_sets disable trigger workout_set_selection_guard;
insert into public.workout_sets(id,owner_id,workout_exercise_id,position,set_type,status,actual_reps,actual_weight_kg,completed_at,deleted_at,entered_weight,entered_unit) values(md5('smart_removed_1')::uuid,md5('smart_a')::uuid,md5('smart_item_removed')::uuid,1,'warm_up','completed',8,99,'2020-01-06',null,null,null);
alter table public.workout_sets enable trigger workout_set_selection_guard;
insert into public.workout_sessions(id,owner_id,name,status,completion_status,started_at,finished_at) values(md5('smart_foreign')::uuid,md5('smart_b')::uuid,'History','completed','partial','2019-12-31','2020-01-07');
insert into public.workout_exercises(id,owner_id,workout_session_id,position,exercise_id,exercise_name_snapshot,removed_at) select md5('smart_item_foreign')::uuid,md5('smart_b')::uuid,md5('smart_foreign')::uuid,1,id,name,null from public.exercises where slug='barbell_bench_press';
insert into public.workout_sets(id,owner_id,workout_exercise_id,position,set_type,status,actual_reps,actual_weight_kg,completed_at,deleted_at,entered_weight,entered_unit) values(md5('smart_foreign_1')::uuid,md5('smart_b')::uuid,md5('smart_item_foreign')::uuid,1,'warm_up','completed',8,99,'2020-01-07',null,null,null);
-- Rollback-only failure injection proves a partially inserted template is atomic.
create function pg_temp.reject_smart_initialization() returns trigger language plpgsql as $$
begin
 if new.position=2 and exists(select 1 from public.workout_exercises where id=new.workout_exercise_id and exercise_name_snapshot='Initialization failure test') then
   raise exception 'Synthetic local preload failure' using errcode='22023';
 end if;
 return new;
end $$;
create trigger smart_test_failure before insert on public.workout_sets for each row execute function pg_temp.reject_smart_initialization();
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('smart_a')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from public.previous_exercise_sets((select id from public.exercises where slug='barbell_bench_press'))),4,'source ignores newer empty/abandoned/removed and other-owner history, pending and deleted sets');
select is((select array_agg(set_type) from public.previous_exercise_sets((select id from public.exercises where slug='barbell_bench_press'))),array['warm_up','working','drop','rest_pause'],'preserves completed sequence and advanced types');
select set_config('body_test.smart_session',public.start_ad_hoc_workout()::text,true);
select set_config('body_test.smart_item',public.edit_workout(current_setting('body_test.smart_session')::uuid,'add',(select id from public.exercises where slug='barbell_bench_press'))::text,true);
select is((select count(*)::int from public.workout_sets where workout_exercise_id=current_setting('body_test.smart_item')::uuid),4,'history defines initial structure');
select ok((select bool_and(status='pending' and actual_reps is null and actual_weight_kg is null and completed_at is null and prescribed_reps_min=8 and prescribed_weight_kg=22.680 and is_automatic and not inputs_confirmed and suggested_from_date='2020-01-01'::timestamptz) from public.workout_sets where workout_exercise_id=current_setting('body_test.smart_item')::uuid),'suggested inputs never become fabricated actual performance');
select lives_ok($$select public.initialize_workout_sets(current_setting('body_test.smart_item')::uuid,6)$$,'retry with another template count leaves existing sets intact');
select is((select count(*)::int from public.workout_sets where workout_exercise_id=current_setting('body_test.smart_item')::uuid),4,'no duplicate initialization');
select lives_ok($$select public.edit_workout(current_setting('body_test.smart_session')::uuid,'remove',null,current_setting('body_test.smart_item')::uuid)$$,'untouched historical suggestions do not block removal');
select set_config('body_test.smart_readded',public.edit_workout(current_setting('body_test.smart_session')::uuid,'add',(select id from public.exercises where slug='barbell_bench_press'))::text,true);
select isnt(current_setting('body_test.smart_readded'),current_setting('body_test.smart_item'),'re-add creates new snapshot rather than resurrecting tombstone');
select set_config('body_test.first_set',(select id::text from public.workout_sets where workout_exercise_id=current_setting('body_test.smart_readded')::uuid order by position limit 1),true);
select lives_ok($$select public.log_workout_set(current_setting('body_test.smart_readded')::uuid,current_setting('body_test.first_set')::uuid,'save',0,md5('smart_complete')::uuid,8,22.68,'warm_up','external',true,null,50,'lb')$$,'confirm original pounds as actual work');
select ok((select inputs_confirmed and actual_reps=8 and actual_weight_kg=22.68 and entered_weight=50 and entered_unit='lb' and status='completed' from public.workout_sets where id=current_setting('body_test.first_set')::uuid),'confirmation preserves precise entry and actual canonical load');
select throws_ok($$select public.edit_workout(current_setting('body_test.smart_session')::uuid,'remove',null,current_setting('body_test.smart_readded')::uuid)$$,'23514',null,'recorded performance protects selection');
select throws_ok($$select public.log_workout_set(current_setting('body_test.smart_readded')::uuid,current_setting('body_test.first_set')::uuid,'save',1,md5('bad_precision')::uuid,8,22.68,'warm_up','external',true,null,99,'lb')$$,'22023',null,'entry metadata cannot misrepresent canonical load');
select set_config('body_test.blank',public.edit_workout(current_setting('body_test.smart_session')::uuid,'add',(select id from public.exercises where slug='push_up'))::text,true);
select is((select count(*)::int from public.workout_sets where workout_exercise_id=current_setting('body_test.blank')::uuid),3,'first use initializes three rows automatically');
select ok((select bool_and(status='pending' and set_type='working' and actual_reps is null and actual_weight_kg is null and prescribed_reps_min is null and prescribed_weight_kg is null and load_mode='bodyweight') from public.workout_sets where workout_exercise_id=current_setting('body_test.blank')::uuid),'first-use rows are blank pending normal sets with appropriate load mode');
select lives_ok($$select public.log_workout_set(current_setting('body_test.blank')::uuid,(select id from public.workout_sets where workout_exercise_id=current_setting('body_test.blank')::uuid order by position limit 1),'remove',0,md5('smart_delete')::uuid)$$,'delete pending automatic row');
select lives_ok($$select public.initialize_workout_sets(current_setting('body_test.blank')::uuid)$$,'resume does not recreate deleted rows');
select is((select count(*)::int from public.workout_sets where workout_exercise_id=current_setting('body_test.blank')::uuid and deleted_at is null),2,'deleted row stays deleted');
select lives_ok($$select public.edit_workout(current_setting('body_test.smart_session')::uuid,'remove',null,current_setting('body_test.blank')::uuid)$$,'deleting a blank automatic row does not create material performance');
select lives_ok($$insert into public.workout_exercises(owner_id,workout_session_id,exercise_id,exercise_name_snapshot,position,prescribed_sets) select auth.uid(),current_setting('body_test.smart_session')::uuid,id,name,20,5 from public.exercises where slug='chin_up'$$,'initializer uses configurable prescribed count');
select is((select count(*)::int from public.workout_sets s join public.workout_exercises e on e.id=s.workout_exercise_id where e.owner_id=auth.uid() and e.workout_session_id=current_setting('body_test.smart_session')::uuid and e.position=20),5,'configured count overrides ad hoc three');
select throws_ok($$insert into public.workout_exercises(owner_id,workout_session_id,exercise_id,exercise_name_snapshot,position,prescribed_sets) select auth.uid(),current_setting('body_test.smart_session')::uuid,id,'Initialization failure test',21,3 from public.exercises where slug='forearm_plank'$$,'22023',null,'initializer failure rolls back the entire add transaction');
select is((select count(*)::int from public.workout_exercises where owner_id=auth.uid() and workout_session_id=current_setting('body_test.smart_session')::uuid and position=21),0,'failed initialization leaves no partial selection');
select set_config('request.jwt.claims',json_build_object('sub',md5('smart_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from public.workout_sets where workout_exercise_id=current_setting('body_test.smart_readded')::uuid),0,'other owner cannot read suggestions');
select throws_ok($$select public.initialize_workout_sets(current_setting('body_test.smart_readded')::uuid)$$,'42501',null,'other owner cannot initialize or overwrite sets');
select is((select count(*)::int from public.previous_exercise_sets((select id from public.exercises where slug='barbell_bench_press'))),1,'history lookup is scoped to caller, not newer foreign source');
select set_config('request.jwt.claims',json_build_object('sub',md5('smart_a')::uuid,'role','authenticated')::text,true);
select public.end_workout(current_setting('body_test.smart_session')::uuid,'completed');
select is((select completion_status from public.workout_sessions where id=current_setting('body_test.smart_session')::uuid),'partial','suggested pending sets do not count as performed');
select throws_ok($$select public.initialize_workout_sets(current_setting('body_test.smart_readded')::uuid)$$,'23514',null,'closed session cannot initialize');
select * from finish();
rollback;
